<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Check, Cpu, Refresh, UploadFilled, Warning } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiErrorMessage, ensureCsrf } from '../services/api'
import type { CandidateContact, ResumeAnalysisFeedbackType, ResumeAnalysisRecommendation, ResumeAnalysisRun, ResumeIntake, ResumeIntakeStatus } from '../types'

const loading=ref(true),saving=ref(false),feedbackSaving=ref(false),errorMessage=ref(''),intakes=ref<ResumeIntake[]>([]),contacts=ref<CandidateContact[]>([]),dialogOpen=ref(false),feedbackDialogOpen=ref(false),analyzingId=ref<string>(),analysisByIntake=ref<Record<string,ResumeAnalysisRun[]>>({})
const form=reactive({contactId:'',displayLabel:'候选人已提供附件简历',reference:''})
const feedbackForm=reactive({runId:'',feedbackType:'ADOPTED' as ResumeAnalysisFeedbackType,note:''})
const pending=computed(()=>intakes.value.filter(item=>item.status==='PENDING_REVIEW'))
const approved=computed(()=>intakes.value.filter(item=>item.status==='APPROVED_FOR_AI'))
const analyzed=computed(()=>Object.values(analysisByIntake.value).flat().filter(item=>item.status==='SUCCEEDED').length)
const statusMeta:Record<ResumeIntakeStatus,{label:string;type:'warning'|'success'|'info'}>={PENDING_REVIEW:{label:'待 HR 审核',type:'warning'},APPROVED_FOR_AI:{label:'已授权 AI',type:'success'},REJECTED:{label:'已拒绝',type:'info'}}
const recommendationMeta:Record<ResumeAnalysisRecommendation,{label:string;type:'success'|'primary'|'warning'}>={PRIORITY_VIEW:{label:'建议优先查看',type:'success'},NORMAL_VIEW:{label:'建议正常查看',type:'primary'},INFORMATION_NEEDED:{label:'信息不足待确认',type:'warning'}}
const feedbackMeta:Record<ResumeAnalysisFeedbackType,{label:string;type:'success'|'warning'|'info'}>={ADOPTED:{label:'作为参考采纳',type:'success'},AMENDED:{label:'HR 已修正',type:'warning'},NOT_USED:{label:'本次未采用',type:'info'}}
const candidateOptions=computed(()=>contacts.value.filter(item=>item.privacyStatus==='ACTIVE'))
function formatDate(value?:string){return value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—'}
function latestAnalysis(id:string){return analysisByIntake.value[id]?.[0]}
async function loadAnalysis(items:ResumeIntake[]){const approvedItems=items.filter(item=>item.status==='APPROVED_FOR_AI');const results=await Promise.all(approvedItems.map(async item=>{const {data}=await api.get<ResumeAnalysisRun[]>(`/resume-intakes/${item.id}/analysis-runs`);return [item.id,data] as const}));analysisByIntake.value=Object.fromEntries(results)}
async function load(){loading.value=true;errorMessage.value='';try{const [intakeResult,contactResult]=await Promise.all([api.get<ResumeIntake[]>('/resume-intakes'),api.get<CandidateContact[]>('/candidate-contacts')]);intakes.value=intakeResult.data;contacts.value=contactResult.data;await loadAnalysis(intakes.value)}catch(error){errorMessage.value=apiErrorMessage(error,'简历登记暂时无法加载')}finally{loading.value=false}}
function openCreate(){form.contactId=candidateOptions.value[0]?.id||'';form.displayLabel='候选人已提供附件简历';form.reference='';dialogOpen.value=true}
async function save(){if(!form.contactId){ElMessage.warning('请选择候选人和岗位');return}if(!form.reference.trim()){ElMessage.warning('请填写仅供生成摘要的内部参考值');return}saving.value=true;try{await ensureCsrf();await api.post(`/candidate-contacts/${form.contactId}/resume-intakes`,{reference:form.reference,displayLabel:form.displayLabel});ElMessage.success('简历事件已登记，等待 HR 审核');dialogOpen.value=false;await load()}catch(error){ElMessage.error(apiErrorMessage(error,'简历登记失败'))}finally{saving.value=false}}
async function review(item:ResumeIntake,decision:Extract<ResumeIntakeStatus,'APPROVED_FOR_AI'|'REJECTED'>){try{const title=decision==='APPROVED_FOR_AI'?'授权进入 AI 分析':'拒绝简历登记';const text=decision==='APPROVED_FOR_AI'?'请先核对简历来源。授权后，仍需在每次分析时明确确认向 OpenAI 发送本次文本。':'该登记将不会进入后续 AI 分析。';const result=await ElMessageBox.prompt(text,title,{inputPlaceholder:'可选审核备注',confirmButtonText:decision==='APPROVED_FOR_AI'?'确认授权':'确认拒绝',cancelButtonText:'取消',type:decision==='APPROVED_FOR_AI'?'success':'warning'});await ensureCsrf();await api.put(`/resume-intakes/${item.id}/review`,{decision,note:result.value||null});ElMessage.success(decision==='APPROVED_FOR_AI'?'已授权，可在需要时提交 OpenAI 分析':'已拒绝该登记');await load()}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(apiErrorMessage(error,'审核失败'))}}
async function analyze(item:ResumeIntake){try{const input=await ElMessageBox.prompt('只粘贴此次分析所需的已审核简历文本（最多 30000 字）。系统不会保存这份原文，但会将其发送给 OpenAI 生成结构化辅助建议。','提交 OpenAI 简历分析',{inputType:'textarea',inputPlaceholder:'粘贴已审核的简历文本',inputValidator:value=>String(value).trim().length>0||'请粘贴简历文本',confirmButtonText:'下一步',cancelButtonText:'取消'});await ElMessageBox.confirm('我确认：已获公司内部授权，可将该候选人的本次简历文本发送至 OpenAI。分析仅供 HR 参考，不会自动淘汰、录用或发送任何消息。','确认外部处理',{type:'warning',confirmButtonText:'确认发送给 OpenAI',cancelButtonText:'取消'});analyzingId.value=item.id;await ensureCsrf();await api.post(`/resume-intakes/${item.id}/analysis`,{resumeText:input.value,externalProcessingConfirmed:true});ElMessage.success('AI 分析已完成，请结合原简历由 HR 做最终判断');await loadAnalysis(intakes.value)}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(apiErrorMessage(error,'OpenAI 分析未完成'))}finally{analyzingId.value=undefined}}
function openFeedback(run:ResumeAnalysisRun){feedbackForm.runId=run.id;feedbackForm.feedbackType='ADOPTED';feedbackForm.note='';feedbackDialogOpen.value=true}
async function saveFeedback(){if(!feedbackForm.note.trim()){ElMessage.warning('请填写 HR 复核说明');return}feedbackSaving.value=true;try{await ensureCsrf();await api.post(`/resume-analysis-runs/${feedbackForm.runId}/feedback`,{feedbackType:feedbackForm.feedbackType,note:feedbackForm.note});ElMessage.success('HR 复核已追加到该次分析记录');feedbackDialogOpen.value=false;await loadAnalysis(intakes.value)}catch(error){ElMessage.error(apiErrorMessage(error,'HR 复核保存失败'))}finally{feedbackSaving.value=false}}
onMounted(load)
</script>

<template><div class="page-shell resume-page">
 <header class="page-heading"><div><span class="eyebrow">RESUME ANALYSIS</span><h1>简历登记与 AI 分析</h1><p>先由 HR 审核简历来源，再按次授权发送必要文本给 OpenAI，得到可追溯的辅助阅读结果。</p></div><div><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button><el-button type="primary" :icon="UploadFilled" @click="openCreate">登记简历事件</el-button></div></header>
 <el-alert type="warning" :closable="false" show-icon title="提交 AI 分析时，已审核的简历文本会发送给 OpenAI。系统不保存该原文，只保存 SHA-256 摘要、结构化结果与审计记录；请勿粘贴与岗位判断无关的敏感信息。"/>
 <div v-if="loading" class="surface-panel skeleton"><el-skeleton :rows="7" animated/></div>
 <div v-else-if="errorMessage" class="surface-panel error"><el-icon><Warning/></el-icon><strong>简历登记暂时无法加载</strong><span>{{errorMessage}}</span><el-button @click="load">重试</el-button></div>
 <template v-else>
  <section class="metrics"><article><span>待 HR 审核</span><strong>{{pending.length}}</strong><small>不会进入 AI</small></article><article><span>已授权 AI</span><strong>{{approved.length}}</strong><small>每次分析仍需确认</small></article><article><span>已完成分析</span><strong>{{analyzed}}</strong><small>仅作 HR 辅助参考</small></article></section>
  <section class="surface-panel"><div class="section-title-row"><div><h2>简历事件队列</h2><p>先完成来源审核；分析时才在浏览器请求中传入原文，系统不将原文写入数据库。</p></div><el-tag type="info">外部模型默认关闭</el-tag></div><el-empty v-if="!intakes.length" :image-size="76" description="尚未登记简历事件"/><div v-else class="intake-list"><article v-for="item in intakes" :key="item.id"><header><div><strong>{{item.candidateName}}</strong><span>{{item.jobTitle}} · {{item.accountName}}</span></div><el-tag :type="statusMeta[item.status].type">{{statusMeta[item.status].label}}</el-tag></header><div class="intake-meta"><span>{{item.displayLabel}}</span><span>摘要 {{item.anonymousKey}}</span><span>登记于 {{formatDate(item.receivedAt)}}</span></div><footer><span>{{item.reviewedAt?`${item.reviewedBy||'HR'} · ${formatDate(item.reviewedAt)}`:'尚未人工审核'}}{{item.reviewNote?` · ${item.reviewNote}`:''}}</span><div v-if="item.status==='PENDING_REVIEW'"><el-button :icon="Check" type="primary" @click="review(item,'APPROVED_FOR_AI')">授权 AI</el-button><el-button plain @click="review(item,'REJECTED')">拒绝</el-button></div><div v-else-if="item.status==='APPROVED_FOR_AI'"><el-button :icon="Cpu" type="primary" :loading="analyzingId===item.id" @click="analyze(item)">提交 AI 分析</el-button></div></footer>
   <section v-if="latestAnalysis(item.id)" class="analysis-card"><template v-if="latestAnalysis(item.id)?.status==='SUCCEEDED'&&latestAnalysis(item.id)?.result"><div class="analysis-heading"><strong>最近一次 OpenAI 分析</strong><div class="analysis-actions"><el-tag :type="recommendationMeta[latestAnalysis(item.id)!.result!.recommendation].type">{{recommendationMeta[latestAnalysis(item.id)!.result!.recommendation].label}}</el-tag><el-button size="small" plain @click="openFeedback(latestAnalysis(item.id)!)">HR 复核</el-button></div></div><p class="analysis-summary">{{latestAnalysis(item.id)!.result!.summary}}</p><div class="analysis-grid"><div><h3>匹配证据</h3><ul><li v-for="evidence in latestAnalysis(item.id)!.result!.evidence" :key="`${evidence.criterion}-${evidence.finding}`"><strong>{{evidence.criterion }}</strong> · {{evidence.finding}} <el-tag size="small" :type="evidence.status==='FOUND'?'success':'info'">{{evidence.status==='FOUND'?'已发现':evidence.status==='NOT_FOUND'?'未发现':'待确认'}}</el-tag></li></ul></div><div><h3>建议追问</h3><ol><li v-for="question in latestAnalysis(item.id)!.result!.followUpQuestions" :key="question">{{question}}</li></ol></div></div><div class="feedback-list"><h3>HR 复核记录</h3><p v-if="!latestAnalysis(item.id)!.feedback.length" class="feedback-empty">尚未复核；此建议不会改变候选人状态。</p><article v-for="entry in latestAnalysis(item.id)!.feedback" :key="entry.id" class="feedback-item"><el-tag size="small" :type="feedbackMeta[entry.feedbackType].type">{{feedbackMeta[entry.feedbackType].label}}</el-tag><span>{{entry.note}}</span><small>{{entry.createdBy}} · {{formatDate(entry.createdAt)}}</small></article></div><small>{{latestAnalysis(item.id)!.provider}} · {{latestAnalysis(item.id)!.modelVersion}} · {{formatDate(latestAnalysis(item.id)!.createdAt)}} · 最终决定由 HR 作出</small></template><template v-else><el-alert type="error" :closable="false" title="最近一次 OpenAI 分析未完成" :description="latestAnalysis(item.id)?.errorMessage||'请检查部署配置后再试'"/></template></section>
  </article></div>
 </section>
 </template>
 <el-dialog v-model="dialogOpen" title="登记简历事件" width="560px"><el-alert type="info" :closable="false" title="这里不是文件上传入口。请只登记“候选人已提供附件/在线简历”等事件，原始资料仅会在 HR 后续主动提交 AI 分析时的单次请求中处理。"/><el-form label-position="top" class="intake-form"><el-form-item label="候选人和岗位" required><el-select v-model="form.contactId" filterable placeholder="选择内部候选人记录"><el-option v-for="item in candidateOptions" :key="item.id" :value="item.id" :label="`${item.displayName} · ${item.jobPosition.title}`"/></el-select></el-form-item><el-form-item label="简历标签" required><el-select v-model="form.displayLabel"><el-option label="候选人已提供附件简历" value="候选人已提供附件简历"/><el-option label="候选人已提供在线简历" value="候选人已提供在线简历"/><el-option label="HR 已人工收到简历" value="HR 已人工收到简历"/></el-select></el-form-item><el-form-item label="内部参考值" required><el-input v-model="form.reference" maxlength="120" placeholder="例如：2026-08-30-附件-01"/><small>仅在浏览器请求中用于生成 SHA-256 摘要；系统不会保存该原文。</small></el-form-item></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认登记</el-button></template></el-dialog>
 <el-dialog v-model="feedbackDialogOpen" title="记录 HR 复核" width="520px"><el-alert type="info" :closable="false" title="这是对 AI 建议的独立人工反馈，不会自动改变候选人状态，也不会发送任何招聘消息。"/><el-form label-position="top" class="intake-form"><el-form-item label="复核结论" required><el-radio-group v-model="feedbackForm.feedbackType"><el-radio-button label="ADOPTED">作为参考采纳</el-radio-button><el-radio-button label="AMENDED">HR 已修正</el-radio-button><el-radio-button label="NOT_USED">本次未采用</el-radio-button></el-radio-group></el-form-item><el-form-item label="HR 复核说明" required><el-input v-model="feedbackForm.note" type="textarea" :rows="4" maxlength="1000" show-word-limit placeholder="例如：已核对项目经历，需在电话沟通中确认实际职责"/></el-form-item></el-form><template #footer><el-button @click="feedbackDialogOpen=false">取消</el-button><el-button type="primary" :loading="feedbackSaving" @click="saveFeedback">保存复核</el-button></template></el-dialog>
</div></template>

<style scoped>
.resume-page{max-width:1380px}.page-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.page-heading>div:last-child{display:flex;gap:10px}.eyebrow{color:var(--primary);font-size:11px;font-weight:800;letter-spacing:.14em}.skeleton,.error{margin-top:20px}.error{display:grid;justify-items:center;gap:10px;padding:48px;color:var(--text-secondary)}.error svg{font-size:28px;color:var(--danger)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.metrics article{padding:18px 20px;border:1px solid var(--border);border-radius:15px;background:#fff;box-shadow:var(--shadow-sm)}.metrics span,.metrics small,.intake-list header span,.intake-list footer>span{display:block;color:var(--text-secondary);font-size:12px}.metrics strong{display:block;margin:7px 0 4px;font-size:28px}.intake-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:0 20px 20px}.intake-list article{padding:17px;border:1px solid var(--border);border-left:4px solid var(--primary);border-radius:13px;background:#fff}.intake-list header,.intake-list footer{display:flex;align-items:center;justify-content:space-between;gap:14px}.intake-list header strong{display:block}.intake-meta{display:grid;gap:7px;margin:16px 0;padding:12px;border-radius:10px;background:var(--surface-muted);color:var(--text-secondary);font-size:12px}.intake-list footer{padding-top:12px;border-top:1px solid var(--border)}.intake-list footer>span{line-height:1.55}.intake-list footer>div{display:flex;gap:8px;flex:0 0 auto}.intake-form{margin-top:18px}.intake-form .el-select{width:100%}.intake-form small,.analysis-card>small{display:block;margin-top:5px;color:var(--text-secondary);font-size:12px;line-height:1.5}.analysis-card{display:grid;gap:12px;margin-top:16px;padding:14px;border-radius:11px;background:#f7fbfb;border:1px solid #d9ece9}.analysis-heading,.analysis-actions{display:flex;align-items:center;justify-content:space-between;gap:10px}.analysis-actions{justify-content:flex-end}.analysis-summary{margin:0;color:var(--text);line-height:1.7}.analysis-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.analysis-grid h3,.feedback-list h3{margin:0 0 7px;font-size:13px}.analysis-grid ul,.analysis-grid ol{display:grid;gap:7px;margin:0;padding-left:18px;color:var(--text-secondary);font-size:12px;line-height:1.55}.analysis-grid strong{color:var(--text)}.analysis-grid .el-tag{margin-left:4px}.feedback-list{display:grid;gap:8px;padding-top:12px;border-top:1px solid #d9ece9}.feedback-empty{margin:0;color:var(--text-secondary);font-size:12px}.feedback-item{display:grid;grid-template-columns:auto 1fr;gap:7px 9px;align-items:start;padding:9px;border-radius:8px;background:#fff;color:var(--text-secondary);font-size:12px;line-height:1.5}.feedback-item small{grid-column:2;color:var(--text-secondary)}@media(max-width:720px){.page-heading{flex-direction:column}.metrics,.intake-list,.analysis-grid{grid-template-columns:1fr}.intake-list header,.intake-list footer{align-items:flex-start;flex-direction:column}.intake-list footer>div{width:100%}.analysis-heading{align-items:flex-start;flex-direction:column}.analysis-actions{width:100%;justify-content:space-between}}
</style>
